import clsx from 'clsx';
import React from 'react';
import type {
  GroupBase,
  MultiValueProps as ReactSelectMultiValueProps,
} from 'react-select';

import { selectMultiValueCSS } from '../styles/Select.sty.js';
import type { _BaseGroup, _BaseOption } from '../types.js';

type MultiValueProps<
  OptionValue,
  isMulti extends boolean,
  Group extends GroupBase<OptionValue>,
> = ReactSelectMultiValueProps<OptionValue, isMulti, Group>;

export function MultiValue<
  OptionValue,
  isMulti extends boolean,
  Group extends _BaseGroup<OptionValue>,
>(props: MultiValueProps<_BaseOption<OptionValue>, isMulti, Group>) {
  const { data } = props;

  return <span className={clsx(selectMultiValueCSS)}>{data.label}</span>;
}
